import{_ as d,o as r,c as e,ag as o}from"./chunks/framework.CAXxHpAX.js";const s=JSON.parse('{"title":"按模型索金句","description":"","frontmatter":{},"headers":[],"relativePath":"40-原话金句/quote-按模型索引.md","filePath":"40-原话金句/quote-按模型索引.md","lastUpdated":1778155802000}'),a={name:"40-原话金句/quote-按模型索引.md"};function u(q,t,h,n,l,b){return r(),e("div",null,[...t[0]||(t[0]=[o('<h1 id="按模型索金句" tabindex="-1">按模型索金句 <a class="header-anchor" href="#按模型索金句" aria-label="Permalink to &quot;按模型索金句&quot;">​</a></h1><blockquote><p>按七大核心模型组织的金句索引。从模型出发，找到对应金句。</p></blockquote><hr><h2 id="天人合一-12条" tabindex="-1">天人合一（12条） <a class="header-anchor" href="#天人合一-12条" aria-label="Permalink to &quot;天人合一（12条）&quot;">​</a></h2><p><strong>世界观：万物一体，因果不空</strong></p><table tabindex="0"><thead><tr><th>#</th><th>金句关键</th><th>出处</th></tr></thead><tbody><tr><td>1</td><td>一滴水与大海融为一体——到底是大海得到一滴水，还是一滴水得到了大海</td><td>quote-佛家</td></tr><tr><td>2</td><td>佛说非身，是名大身——真正的&quot;大&quot;是跟宇宙一样大</td><td>quote-佛家</td></tr><tr><td>3</td><td>心佛众生，三无差别</td><td>quote-佛家</td></tr><tr><td>4</td><td>宇宙的能量场有无穷无尽的频道，我们通过修行慢慢与更多的场同步共振</td><td>quote-丹道</td></tr><tr><td>5</td><td>若菩萨通达无我法者，如来说名真是菩萨</td><td>quote-佛家</td></tr><tr><td>6</td><td>道无处不在。你不需要去远方找道，就在你眼前</td><td>quote-道家</td></tr><tr><td>7</td><td>人法地，地法天，天法道，道法自然</td><td>quote-道家</td></tr><tr><td>8</td><td>道家增强内气从而增强外场；佛家增强外场而增强内气。最高境界亲证实相，就是零维</td><td>quote-丹道</td></tr><tr><td>9</td><td>贯穿身体内外的混元气场不是练出来的，而是融进去的</td><td>quote-丹道</td></tr><tr><td>10</td><td>观天之道，执天之行——观察大自然的规律，并以此规范我们的行为</td><td>quote-道家</td></tr><tr><td>11</td><td>六道皆是妄想所变幻，犹如开心伤心变幻出笑容泪水</td><td>quote-佛家</td></tr><tr><td>12</td><td>一切不永恒，所以可改变，不必执</td><td>quote-佛家</td></tr></tbody></table><hr><h2 id="对境不住-14条" tabindex="-1">对境不住（14条） <a class="header-anchor" href="#对境不住-14条" aria-label="Permalink to &quot;对境不住（14条）&quot;">​</a></h2><p><strong>心法：不被现象迷惑，保持清净</strong></p><table tabindex="0"><thead><tr><th>#</th><th>金句关键</th><th>出处</th></tr></thead><tbody><tr><td>1</td><td>保持平静的要诀就是保持理智地去看待一切</td><td>quote-佛家</td></tr><tr><td>2</td><td>不平静时问自己：我为什么要不平静？这样正确吗？</td><td>quote-佛家</td></tr><tr><td>3</td><td>应无所住而生其心——心不要停在任何一个地方</td><td>quote-佛家</td></tr><tr><td>4</td><td>过去心不可得，现在心不可得，未来心不可得</td><td>quote-佛家</td></tr><tr><td>5</td><td>若见诸相非相，即见如来</td><td>quote-佛家</td></tr><tr><td>6</td><td>凡所有相，皆是虚妄——不永恒的，不要被它骗了</td><td>quote-佛家</td></tr><tr><td>7</td><td>知见无见，斯即涅槃——知道但不执着于任何观点</td><td>quote-佛家</td></tr><tr><td>8</td><td>不怕念起，只怕觉迟</td><td>quote-佛家</td></tr><tr><td>9</td><td>入静并非一念不生。真禅定者心如明镜高悬</td><td>quote-佛家</td></tr><tr><td>10</td><td>要无住生心——该住就住，不该住就不住</td><td>quote-佛家</td></tr><tr><td>11</td><td>致虚极，守静笃——把心放空到极致，万物的真相就现前</td><td>quote-道家</td></tr><tr><td>12</td><td>有之以为利，无之以为用——放空了才有用</td><td>quote-道家</td></tr><tr><td>13</td><td>五色令人目盲——不是不要，是不要被它们牵着走</td><td>quote-道家</td></tr><tr><td>14</td><td>静坐时杂念来了，看着它，不跟随，不攀缘，它自然就消失</td><td>quote-丹道</td></tr></tbody></table><hr><h2 id="对法不执-14条" tabindex="-1">对法不执（14条） <a class="header-anchor" href="#对法不执-14条" aria-label="Permalink to &quot;对法不执（14条）&quot;">​</a></h2><p><strong>心法：连修行方法、功德也放下</strong></p><table tabindex="0"><thead><tr><th>#</th><th>金句关键</th><th>出处</th></tr></thead><tbody><tr><td>1</td><td>法尚应舍，何况非法——法是指南针，不是终点</td><td>quote-佛家</td></tr><tr><td>2</td><td>所谓佛法者，即非佛法——药方不能通用</td><td>quote-佛家</td></tr><tr><td>3</td><td>无有定法名阿耨多罗三藐三菩提——没有一个固定的方法叫开悟</td><td>quote-佛家</td></tr><tr><td>4</td><td>庄严佛土者，即非庄严，是名庄严——没有&quot;我在做好事&quot;的念头</td><td>quote-佛家</td></tr><tr><td>5</td><td>实无有法名阿罗汉——不觉得自己证得了什么，才是真正的证得</td><td>quote-佛家</td></tr><tr><td>6</td><td>法无定法，各人因缘不同。不要拿自己的法门去评判别人的</td><td>quote-佛家</td></tr><tr><td>7</td><td>我不守五戒，念佛有用吗？有用。因果是一条一条来的</td><td>quote-佛家</td></tr><tr><td>8</td><td>从金刚经来说，不必执着有没有阿弥陀佛来接引，对一切相不着是真正上品上生</td><td>quote-佛家</td></tr><tr><td>9</td><td>功法和门派殊途同归，到大周天后都是无为的</td><td>quote-丹道</td></tr><tr><td>10</td><td>聚气是有为法，是我执，跟大自然能量场不沟通</td><td>quote-丹道</td></tr><tr><td>11</td><td>释迦牟尼佛六年苦修不是渐悟，是没有明师引路</td><td>quote-佛家</td></tr><tr><td>12</td><td>不要追求境界，境界自然会来。越追越跑</td><td>quote-丹道</td></tr><tr><td>13</td><td>有境界不执着，没有境界不着急。每个人因缘不同</td><td>quote-丹道</td></tr><tr><td>14</td><td>万法平等在果——坐飞机和走路都能到北京</td><td>quote-丹道</td></tr></tbody></table><hr><h2 id="自然务实-14条" tabindex="-1">自然务实（14条） <a class="header-anchor" href="#自然务实-14条" aria-label="Permalink to &quot;自然务实（14条）&quot;">​</a></h2><p><strong>方法论：抓核心，做实事，生活即修行</strong></p><table tabindex="0"><thead><tr><th>#</th><th>金句关键</th><th>出处</th></tr></thead><tbody><tr><td>1</td><td>一切贤圣，皆以无为法而有差别——方法有快慢，都到彼岸</td><td>quote-佛家</td></tr><tr><td>2</td><td>信心不逆——知行合一才是真信</td><td>quote-佛家</td></tr><tr><td>3</td><td>以无我无人修一切善法，即得阿耨多罗三藐三菩提——行善同时就符合成佛标准</td><td>quote-佛家</td></tr><tr><td>4</td><td>认真工作也是禅定。生活处处是道场</td><td>quote-佛家</td></tr><tr><td>5</td><td>为学日益，为道日损——减少的是执着和妄念</td><td>quote-道家</td></tr><tr><td>6</td><td>上善若水——水善利万物而不争</td><td>quote-道家</td></tr><tr><td>7</td><td>天下难事必作于易，天下大事必作于细</td><td>quote-道家</td></tr><tr><td>8</td><td>千里之行，始于足下——走起来最重要</td><td>quote-道家</td></tr><tr><td>9</td><td>少则得，多则惑——专注一件事，反而能做成</td><td>quote-道家</td></tr><tr><td>10</td><td>因上精进，果上随缘——过程努力，结果不执着</td><td>quote-儒家</td></tr><tr><td>11</td><td>凡事尽力而为，做人问心无愧</td><td>quote-儒家</td></tr><tr><td>12</td><td>看见人家丑恶的一面时，应立刻检点自己</td><td>quote-儒家</td></tr><tr><td>13</td><td>练功的姿势行住坐卧都可以——意念轻轻观察身体</td><td>quote-丹道</td></tr><tr><td>14</td><td>做就是了。行动胜过千言万语</td><td>quote-儒家</td></tr></tbody></table><hr><h2 id="圆融中和-14条" tabindex="-1">圆融中和（14条） <a class="header-anchor" href="#圆融中和-14条" aria-label="Permalink to &quot;圆融中和（14条）&quot;">​</a></h2><p><strong>处世智慧：不走极端，中道而行</strong></p><table tabindex="0"><thead><tr><th>#</th><th>金句关键</th><th>出处</th></tr></thead><tbody><tr><td>1</td><td>是故不应取法，不应取非法——不执有也不执空</td><td>quote-佛家</td></tr><tr><td>2</td><td>如来所说法，皆不可取，不可说——要具体问题具体分析</td><td>quote-佛家</td></tr><tr><td>3</td><td>若作是言&quot;我当灭度无量众生&quot;，即不名菩萨——觉得自己度了很多人就不是菩萨</td><td>quote-佛家</td></tr><tr><td>4</td><td>多言数穷，不如守中——守中不是停在中间，是不断微调方向</td><td>quote-道家</td></tr><tr><td>5</td><td>知其雄，守其雌——知道自己的力量，但要保持谦卑</td><td>quote-道家</td></tr><tr><td>6</td><td>夫唯不争，故天下莫能与之争——没有对手位置就不可能被争</td><td>quote-道家</td></tr><tr><td>7</td><td>挫其锐，解其纷，和其光，同其尘</td><td>quote-道家</td></tr><tr><td>8</td><td>知足不辱，知止不殆</td><td>quote-道家</td></tr><tr><td>9</td><td>天之道，损有余而补不足</td><td>quote-道家</td></tr><tr><td>10</td><td>什么叫做正，不偏不倚谓之正。自利利他</td><td>quote-儒家</td></tr><tr><td>11</td><td>心胸不用宽广也不用狭隘，以智慧去看待一切</td><td>quote-儒家</td></tr><tr><td>12</td><td>该花一万不会花九千，不该花的五元都不愿意花</td><td>quote-儒家</td></tr><tr><td>13</td><td>整体观定善恶——看前因后果才知道好坏</td><td>quote-儒家</td></tr><tr><td>14</td><td>守中——不走极端，像开车微调方向保持在车道中间</td><td>quote-道家</td></tr></tbody></table><hr><h2 id="历境炼心-14条" tabindex="-1">历境炼心（14条） <a class="header-anchor" href="#历境炼心-14条" aria-label="Permalink to &quot;历境炼心（14条）&quot;">​</a></h2><p><strong>实践：在每一个境遇中磨炼</strong></p><table tabindex="0"><thead><tr><th>#</th><th>金句关键</th><th>出处</th></tr></thead><tbody><tr><td>1</td><td>一切法皆是佛法——只要不执着，一切现象都能成为觉悟的契机</td><td>quote-佛家</td></tr><tr><td>2</td><td>烦恼即菩提——烦恼是你修行的机会</td><td>quote-佛家</td></tr><tr><td>3</td><td>家庭是道场，工作单位是道场，社会是道场</td><td>quote-儒家</td></tr><tr><td>4</td><td>冤亲平等——对伤害你的人和对帮助你的人保持同样的心</td><td>quote-儒家</td></tr><tr><td>5</td><td>别人对不起你，你原谅他，不是因为你懦弱，是因为你大气</td><td>quote-儒家</td></tr><tr><td>6</td><td>若真修道人，不见世间过——不是看不到，是看到不起烦恼</td><td>quote-儒家</td></tr><tr><td>7</td><td>忍耐不是懦夫，忍是留下余地，留下主动权</td><td>quote-儒家</td></tr><tr><td>8</td><td>顺境不沉溺，逆境不气馁——保持平常心</td><td>quote-儒家</td></tr><tr><td>9</td><td>人生就是一场修行，遇到的每个人每件事都是来度你的</td><td>quote-儒家</td></tr><tr><td>10</td><td>南泉斩猫——不是真杀猫，是斩断心里的&quot;猫&quot;（执着）</td><td>quote-佛家</td></tr><tr><td>11</td><td>赵州茶——&quot;吃茶去！&quot;修行就在喝茶吃饭日常之中</td><td>quote-佛家</td></tr><tr><td>12</td><td>归宗斩蛇——跳出局部，看全局</td><td>quote-佛家</td></tr><tr><td>13</td><td>司空见惯就是平常心</td><td>quote-儒家</td></tr><tr><td>14</td><td>开悟不是毕业，开悟是入学了。悟后起修</td><td>quote-佛家</td></tr></tbody></table><hr><h2 id="性命双修-16条" tabindex="-1">性命双修（16条） <a class="header-anchor" href="#性命双修-16条" aria-label="Permalink to &quot;性命双修（16条）&quot;">​</a></h2><p><strong>实修：身心一体，性命并重</strong></p><table tabindex="0"><thead><tr><th>#</th><th>金句关键</th><th>出处</th></tr></thead><tbody><tr><td>1</td><td>养气忘言守，降心为不为</td><td>quote-丹道</td></tr><tr><td>2</td><td>神守黄房，金胎自成</td><td>quote-丹道</td></tr><tr><td>3</td><td>不可用心守，不可无意求</td><td>quote-丹道</td></tr><tr><td>4</td><td>似守非守——在有心无心之间。轻轻知道，轻轻放下</td><td>quote-丹道</td></tr><tr><td>5</td><td>行住坐卧，绵绵若存</td><td>quote-丹道</td></tr><tr><td>6</td><td>我师父以师力加持，刹那间就通大周天了</td><td>quote-丹道</td></tr><tr><td>7</td><td>师力加持就是能量共振，融进师父气场</td><td>quote-丹道</td></tr><tr><td>8</td><td>但安神息，不运火而火自运——心平气和，火候自然</td><td>quote-丹道</td></tr><tr><td>9</td><td>先天元神元炁，刻刻相合，渐渐相化</td><td>quote-丹道</td></tr><tr><td>10</td><td>身体虚无，精神状态好——形神俱妙</td><td>quote-丹道</td></tr><tr><td>11</td><td>修行的目的是明心见性，不是神通</td><td>quote-丹道</td></tr><tr><td>12</td><td>百日功夫——不是天数，是提醒坚持</td><td>quote-丹道</td></tr><tr><td>13</td><td>练功无论行住坐卧都可以——轻轻观察身体和念头</td><td>quote-丹道</td></tr><tr><td>14</td><td>火候无差跟瓜熟蒂落一致，是自然的。道法自然</td><td>quote-道家</td></tr><tr><td>15</td><td>致虚极，守静笃——静到极处真相现前</td><td>quote-道家</td></tr><tr><td>16</td><td>修行人最重要的是至诚恭敬之心，我心中也以所遇之人为师</td><td>quote-佛家</td></tr></tbody></table><hr><blockquote><p>更新日期：2026-05-07（按新4传统分类文件更新引用；新增30+条金句；各模型扩充至12-16条）</p></blockquote>',32)])])}const c=d(a,[["render",u]]);export{s as __pageData,c as default};
